/* Lesson s5c-images-in: sending images to a model.
   Story: an expense app where staff photograph taxi and restaurant receipts on their phones and a small hosted
   vision model turns each photo into fields (date, subtotal, tax, tip, total, currency).
   Ideas: (1) the model answers from the pixels it gets and fills every field it is asked for, even when the
   pixels do not hold the answer: a blurred or tiny photo comes back as a confident, self-consistent, wrong
   receipt, and a cropped one gets a total that was never in the photo. (2) So the preparation happens in code,
   before and after the call: check the photo (sharpness, size) and ask for a retake, let the answer say null for a
   field it cannot see, and know when a photo is the wrong input altogether (OCR and rules, a barcode decoder, or
   the data that already exists as data).
   Depth: explain (screens 1-6, interview), when-not (screens 7 and 8).
   Data, all real:
   - photos made by docs/ai-path/runs/s5c-images-in/make_receipts.py (made-up receipt, drawn with Pillow; the
     truth is make_receipts.out.txt), make_turned.py, make_tilted_medium.py; prep.py -> prep.out.txt (blur scores,
     the found tilt, the sharpened and medium copies); thumbs.py -> thumbs.out.txt (the display copies below);
   - model answers: recordings in the main checkout, docs/ai-path/recordings/s5c-images-in/<name>.json (openrouter,
     google/gemini-2.5-flash-lite, temperature 0, 2026-11-13), copied by to_js.py -> to_js.out.txt (the ask field dropped), not altered.
   Lesson-local style (.lx-s5c-images-in-*): photo cards, field buttons, the raw answer block. See ensureStyle().
   Every number on screen is computed here from TRUTH, REC and PREP. Plain browser script. */
(() => {
  const ID = "s5c-images-in";
  const P = `lx-${ID}-`;
  const plural = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`;
  const WORDS = ["no", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"];
  const word = n => WORDS[n] || String(n);

  /* ---------- Data copied from the runs (not altered) ---------- */
  // From docs/ai-path/runs/s5c-images-in/make_receipts.out.txt: what the paper says.
  const TRUTH = {"merchant": "Lantern Noodle House", "date": "2026-10-14", "subtotal": "44.50", "tax": "3.56", "tip": "8.00", "total": "56.06", "currency": "USD"};
  // From docs/ai-path/runs/s5c-images-in/prep.out.txt.
  const PREP = {"blur": {"clean": 1453.5, "blurred": 1.6, "tilted": 982.6, "cropped": 2111.5, "small": 1415.3, "upright": 730.1, "sharpened": 15.2}, "tilt": 38};
  // From docs/ai-path/runs/s5c-images-in/to_js.out.txt (recordings docs/ai-path/recordings/s5c-images-in/<name>.json):
  // text = the model's reply exactly as returned; promptTokens = usage.prompt_tokens; system = the system prompt sent.
  const REC = {"runs": {"clean": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "blurred": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2024-10-16\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"5.56\",\n  \"tip\": \"4.00\",\n  \"total\": \"54.06\",\n  \"currency\": \"USD\"\n}\n```"}, "tilted": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "cropped": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "small": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2023-02-14\",\n  \"subtotal\": \"46.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"4.00\",\n  \"total\": \"54.06\",\n  \"currency\": \"CAD\"\n}\n```"}, "medium": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "upright": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "sharpened": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2024-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"6.00\",\n  \"total\": \"54.06\",\n  \"currency\": \"USD\"\n}\n```"}, "cropped-allow": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 344, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals. If a field is not visible in the photo, or you cannot read it for certain, use null for it.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": null,\n  \"currency\": null\n}\n```"}, "blurred-allow": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 344, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals. If a field is not visible in the photo, or you cannot read it for certain, use null for it.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2024-05-16\",\n  \"subtotal\": \"46.50\",\n  \"tax\": \"5.56\",\n  \"tip\": \"6.00\",\n  \"total\": \"58.06\",\n  \"currency\": \"USD\"\n}\n```"}, "sideways": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "upside": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}, "tilted-medium": {"model": "google/gemini-2.5-flash-lite", "date": "2026-11-13", "promptTokens": 321, "system": "You read receipt photos for an expense app. Reply with JSON only, no other text, with exactly these keys: merchant, date (YYYY-MM-DD), subtotal, tax, tip, total, currency (3-letter code). Write amounts as strings with two decimals.", "text": "```json\n{\n  \"merchant\": \"LANTERN NOODLE HOUSE\",\n  \"date\": \"2026-10-14\",\n  \"subtotal\": \"44.50\",\n  \"tax\": \"3.56\",\n  \"tip\": \"8.00\",\n  \"total\": \"56.06\",\n  \"currency\": \"USD\"\n}\n```"}}};
  // From docs/ai-path/runs/s5c-images-in/thumbs.out.txt: display copies (240 px wide; "small" is the file as sent).
  const PHOTOS = {"clean": {"w": 240, "h": 347, "src": "data:image/jpeg;base64,"}, "blurred": {"w": 240, "h": 347, "src": "data:image/jpeg;base64,"}, "tilted": {"w": 240, "h": 347, "src": "data:image/jpeg;base64,"}, "cropped": {"w": 240, "h": 199, "src": "data:image/jpeg;base64,"}, "small": {"w": 152, "h": 220, "src": "data:image/jpeg;base64,"}, "sharpened": {"w": 240, "h": 347, "src": "data:image/jpeg;base64,"}};
  // The photo sizes the model got (make_receipts.out.txt, prep.out.txt).
  const SENT_SIZE = { clean: [760, 1100], small: [152, 220], medium: [380, 550], blurred: [760, 1100], tilted: [760, 1100], cropped: [760, 630] };
  const SIZE_OF = run => SENT_SIZE[run];

  /* ---------- Derived from the data ---------- */
  const R = REC.runs;
  const DATE = R.clean.date;
  const CAPTION = `Recorded model output, ${DATE}`;
  const parse = t => JSON.parse(t.replace(/^```json\s*/, "").replace(/```\s*$/, ""));
  const ANS = Object.fromEntries(Object.keys(R).map(k => [k, parse(R[k].text)]));
  const FIELDS = ["date", "subtotal", "tax", "tip", "total", "currency"];
  const isWrong = (run, f) => ANS[run][f] !== TRUTH[f];
  const wrongOf = run => FIELDS.filter(f => isWrong(run, f));
  const ROWS = [["blurred", "Blurred"], ["tilted", "Tilted"], ["cropped", "Cropped"], ["small", "Thumbnail"]];
  const TARGETS = ROWS.flatMap(([run]) => wrongOf(run).map(f => `${run}:${f}`));
  const cents = s => Math.round(parseFloat(s) * 100);
  const money = c => (c / 100).toFixed(2);
  const sumOf = a => cents(a.subtotal) + cents(a.tax) + cents(a.tip);
  const adds = run => sumOf(ANS[run]) === cents(ANS[run].total);
  const nulls = run => FIELDS.filter(f => ANS[run][f] === null);
  const wrongNotNull = run => FIELDS.filter(f => ANS[run][f] !== null && isWrong(run, f));
  const SYS_EXTRA = R["cropped-allow"].system.slice(R.cropped.system.length).trim();
  const SHARP = PREP.blur.sharpened, BLUR = PREP.blur;
  const MERCHANT_SAME = Object.values(ANS).every(a => a.merchant.toLowerCase() === TRUTH.merchant.toLowerCase());
  const TILT_OK = ["tilted", "sideways", "upside", "tilted-medium"].filter(k => wrongOf(k).length === 0).length;
  const pxRatio = (a, b) => Math.round((SENT_SIZE[a][0] * SENT_SIZE[a][1]) / (SENT_SIZE[b][0] * SENT_SIZE[b][1]));

  /* ---------- Lesson-local style and helpers ---------- */
  function ensureStyle() {
    if (document.getElementById(P + "css")) return;
    const s = document.createElement("style");
    s.id = P + "css";
    s.textContent = `
      .${P}truth { margin: 14px 0 0; display: flex; flex-wrap: wrap; gap: 6px 14px; font: 500 14px/1.5 var(--mono); color: var(--ink); padding: 10px 12px; border: 1.5px solid var(--line); border-radius: 8px; background: var(--sunk); }
      .${P}truth span b { font-weight: 700; }
      .${P}truth span i { font-style: normal; color: var(--muted); margin-right: 4px; }
      .${P}card { margin: 16px 0 0; padding: 12px; border: 1.5px solid var(--line); border-radius: 10px; background: var(--surface); display: grid; grid-template-columns: 96px 1fr; gap: 12px; align-items: start; }
      .${P}card h3 { margin: 0 0 8px; font: 600 15px/1.3 var(--font); color: var(--ink); grid-column: 1 / -1; }
      .${P}card img { width: 96px; height: auto; border-radius: 4px; display: block; }
      .${P}card img.${P}true { width: auto; max-width: 96px; }
      .${P}fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
      .${P}fields button, .${P}fields div { min-height: 44px; padding: 6px 8px; border: 1.5px solid var(--line); border-radius: 8px; background: var(--bg); color: var(--ink); font: 500 14px/1.3 var(--mono); text-align: left; overflow-wrap: anywhere; }
      .${P}fields button { cursor: pointer; }
      .${P}fields small { display: block; font: 500 11.5px/1.3 var(--font); color: var(--muted); }
      .${P}fields .right { border-color: var(--good); background: var(--good-soft); }
      .${P}fields .wrong { border-color: var(--bad); background: var(--bad-soft); }
      .${P}fields .missing { border-style: dashed; }
      @media (hover: hover) { .${P}fields button:not(.right):not(.wrong):hover { border-color: var(--ink); } }
      .${P}raw { margin: 10px 0 0; grid-column: 1 / -1; }
      .${P}raw summary { cursor: pointer; font: 500 13px/1.5 var(--font); color: var(--muted); min-height: 44px; display: flex; align-items: center; }
      .${P}raw pre { margin: 0; padding: 8px 10px; background: var(--sunk); border-radius: 6px; font: 500 12.5px/1.45 var(--mono); white-space: pre-wrap; overflow-wrap: anywhere; color: var(--ink); }
      .${P}cap { margin: 6px 0 0; font-size: 13px; color: var(--muted); }
      .${P}pics { display: flex; flex-wrap: wrap; gap: 12px; margin: 14px 0 0; align-items: flex-end; }
      .${P}pics figure { margin: 0; }
      .${P}pics img { display: block; width: 140px; height: auto; border-radius: 4px; }
      .${P}pics img.${P}true { width: auto; }
      .${P}pics figcaption { font: 500 12.5px/1.4 var(--font); color: var(--muted); margin-top: 4px; max-width: 160px; }
      .${P}msg { margin: 12px 0 0; padding: 10px 12px; border-left: 3px solid var(--line); background: var(--sunk); font: 500 14px/1.5 var(--mono); white-space: pre-wrap; overflow-wrap: anywhere; }
      .${P}wrap .lcode div { white-space: pre-wrap; overflow-wrap: anywhere; padding-left: calc(12px + 4ch); text-indent: -4ch; }
      .${P}scores { margin: 14px 0 0; border-collapse: collapse; width: 100%; font: 500 14px/1.4 var(--mono); }
      .${P}scores th, .${P}scores td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--line); }
      .${P}scores th { font: 600 12.5px/1.4 var(--font); color: var(--muted); }
      .${P}scores td.n { text-align: right; }
    `;
    document.head.appendChild(s);
  }
  const img = (kit, run, alt) => {
    const p = PHOTOS[run];
    return `<img src="${p.src}" width="${p.w}" height="${p.h}" alt="${kit.esc(alt)}"${run === "small" ? ` class="${P}true"` : ""}>`;
  };
  const fig = (kit, run, text) => `<figure>${img(kit, run, text)}<figcaption>${kit.esc(text)}</figcaption></figure>`;
  const truthLine = kit => `<div class="${P}truth" aria-label="What the paper says">${FIELDS.map(f => `<span><i>${f}</i><b>${kit.esc(TRUTH[f])}</b></span>`).join("")}</div>`;
  const raw = (kit, run) => `<details class="${P}raw"><summary>The model's exact reply</summary><pre>${kit.esc(R[run].text)}</pre></details>`;
  const ask = (kit, opts, correct, picked, fbs) => `${kit.options(opts, { picked, correct })}${picked == null ? "" : kit.feedback(fbs[picked][0], fbs[picked][1])}`;
  const fieldList = fs => fs.length ? fs.join(", ") : "none";

  /* 1. The situation, then by hand: which fields did the model get wrong? */
  function markWrong({ el, done, kit }) {
    ensureStyle();
    const found = new Set();
    let miss = null;
    const paint = () => {
      const fin = found.size === TARGETS.length;
      el.innerHTML = `<h1>Four photos of one receipt</h1>
        <p class="lead">Staff at a small company photograph their taxi and restaurant receipts with their phones. The expense app sends each photo to a small hosted vision model (a model that can read images) and asks it for the fields as JSON. At the end of the month, finance found wrong amounts, and nobody could say why.</p>
        <p class="lead">This lesson is about that step in an AI product: getting a photo ready so the model reads it right, and knowing when not to send a photo at all.</p>
        <p class="lead">Here is one dinner receipt, sent four ways. This is what the paper says:</p>
        ${truthLine(kit)}
        <p class="task">Tap every field the model got wrong. The photos are shown small here; the model got them full size.</p>
        ${ROWS.map(([run, label]) => `<div class="${P}card" id="r-${run}"><h3>${kit.esc(label)} <small style="font-weight:500;color:var(--muted)">sent at ${SIZE_OF(run).join(" × ")} pixels</small></h3>${img(kit, run, `${label} photo of the receipt`)}<div class="${P}fields">${FIELDS.map(f => {
          const k = `${run}:${f}`, st = found.has(k) ? "wrong" : "";
          return `<button type="button" data-k="${k}" class="${st}"><small>${f}</small>${kit.esc(ANS[run][f])}</button>`;
        }).join("")}</div>${raw(kit, run)}</div>`).join("")}
        <p class="${P}cap">${CAPTION}</p>
        <div class="lpanel">${fin
          ? kit.feedback(`Found all ${TARGETS.length}. ${ROWS.map(([run, label]) => `${label}: ${plural(wrongOf(run).length, "wrong field")}`).join(". ")}. The merchant name was ${MERCHANT_SAME ? "read right on every photo" : "not always right"}. The blurred and the thumbnail answers look as sure as the others: nothing in the JSON says “I could not read this”.`, true)
          : miss ? kit.feedback(miss.say, false)
          : found.size ? kit.feedback(`${found.size} of the wrong fields found. Keep comparing with the paper.`) : ""}</div>`;
      el.querySelectorAll(`.${P}fields button`).forEach(b => b.onclick = () => {
        if (found.size === TARGETS.length) return;
        const k = b.dataset.k, [run, f] = k.split(":");
        if (TARGETS.includes(k)) { found.add(k); miss = null; }
        else {
          const label = ROWS.find(r => r[0] === run)[1];
          miss = { k, say: run === "cropped" && f === "total"
            ? `The ${label.toLowerCase()} answer says total ${kit.esc(ANS[run][f])}, and the paper says ${kit.esc(TRUTH[f])}: it matches. Keep it in mind; the next screens come back to it.`
            : `${label}, ${f}: the model said ${kit.esc(ANS[run][f])} and the paper says ${kit.esc(TRUTH[f])}. That one is right. Look for fields that differ from the paper.` };
        }
        paint();
        if (found.size === TARGETS.length) done();
      });
    };
    paint();
  }

  /* 2. Predict: would an arithmetic check catch the wrong answers? */
  function sumCheck({ el, done, kit }) {
    ensureStyle();
    const CHECK = ["blurred", "small"];
    const ans = CHECK.map(() => null);
    const paint = () => {
      const all = CHECK.every((run, i) => ans[i] === (adds(run) ? 1 : 0));
      el.innerHTML = `<h1>Would an arithmetic check catch them?</h1>
        <p class="lead">A colleague suggests a cheap check in code: accept an answer only if subtotal + tax + tip equals total. A misread digit should break the sum.</p>
        <p class="task">For each wrong answer, predict whether the check catches it.</p>
        ${CHECK.map((run, i) => {
          const a = ANS[run], label = ROWS.find(r => r[0] === run)[1], right = adds(run) ? 1 : 0;
          const line = `${a.subtotal} + ${a.tax} + ${a.tip} = ${money(sumOf(a))}`;
          return `<div class="lcase" id="c${i}"><p><b>${label}</b>: subtotal ${kit.esc(a.subtotal)}, tax ${kit.esc(a.tax)}, tip ${kit.esc(a.tip)}, total ${kit.esc(a.total)}. Wrong fields: ${kit.esc(fieldList(wrongOf(run)))}.</p>${kit.options(["The check catches it", "It passes the check"], { picked: ans[i], correct: right })}${ans[i] == null ? "" : kit.feedback(ans[i] === right
            ? `Right. ${line}, and the total says ${kit.esc(a.total)}. ${adds(run) ? "The numbers agree with each other, so the check passes, though the paper says otherwise." : "The sum breaks, so the check catches it."}`
            : adds(run) ? `Add them up: ${line}. The model's total says ${kit.esc(a.total)}. The wrong numbers agree with each other, so the check lets this answer through.`
            : `Add them up: ${line}, but the total says ${kit.esc(a.total)}. The sum breaks, so the check does catch it.`, ans[i] === right)}</div>`;
        }).join("")}
        ${all ? kit.feedback(`The check passed ${word(CHECK.filter(adds).length)} of ${word(CHECK.length)} wrong answers. ${adds("sharpened") ? "So does an answer you will meet later, for a sharpened copy of the blurred photo. " : ""}The model did not report the digits it could see and leave gaps for the rest: it wrote a whole receipt that hangs together. A check that only compares the answer with itself cannot tell a good read from a tidy guess.`) : ""}`;
      el.querySelectorAll(".lcase").forEach((c, i) => c.querySelectorAll("button").forEach(b => b.onclick = () => {
        ans[i] = +b.dataset.i; paint();
        if (CHECK.every((run, j) => ans[j] === (adds(run) ? 1 : 0))) done();
      }));
    };
    paint();
  }

  /* 3. Spot the idea: the cropped answer was right, but the total was not in the photo. */
  function spotIdea({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const a = ANS.cropped;
    const opts = [
      "Part of the total line was still in the photo, and the model read it.",
      "The prompt asked for every field, so it filled in a total and a currency it could not see.",
      "The model remembered this receipt from the earlier calls, when it saw the whole photo.",
      "It was luck, and it came out right, so the cropped photo is not a problem."
    ];
    const fb = [
      [`Look at the photo: it ends under the tip line. The word TOTAL, the amount and the currency are all below the cut. There was nothing of them to read.`, false],
      [`Right. The lines it could see add up: ${a.subtotal} + ${a.tax} + ${a.tip} = ${money(sumOf(a))}${sumOf(a) === cents(a.total) ? ", the number it gave as the total" : ""}, and the currency was a guess. This time the guess matched the paper, but it was still a guess. A receipt with a service charge or a discount below the cut would get a total that is wrong and looks right. The model will not tell you which fields it saw and which it made up. So two jobs belong to your code: check the photo before the call, and let the answer say “not visible” so a missing field can be caught.`, true],
      [`Each call is separate. The request carries only its own messages and this one photo, and the model keeps nothing between calls. It never saw the full receipt in this call.`, false],
      [`It came out right this time, and that is the danger. The app cannot tell this answer from a read one, so it would accept a wrong one the same way. A total that was never in the photo should not reach finance as if it had been read.`, false]
    ];
    const paint = () => {
      el.innerHTML = `<h1>A right total that was never in the photo</h1>
        <p class="lead">The cropped photo stops just under the tip line, yet the model answered total <b>${kit.esc(a.total)}</b> and currency <b>${kit.esc(a.currency)}</b>, the same as the paper.</p>
        <div class="${P}pics">${fig(kit, "cropped", "Cropped: the photo ends under the tip line")}</div>
        <p class="${P}cap">${CAPTION}</p>
        <p class="task">Where did that total come from?</p>
        <div class="lpanel">${ask(kit, opts.map(kit.esc), 1, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === 1) done(); });
    };
    paint();
  }

  /* 4. Predict three recorded fixes: a prompt that allows null, on cropped and on blurred; a sharpening filter. */
  function predictFixes({ el, done, kit }) {
    ensureStyle();
    const ans = [null, null, null];
    const ca = ANS["cropped-allow"], ba = ANS["blurred-allow"];
    const Q = [
      { q: `The app adds one sentence to the system prompt:<span class="${P}msg" style="display:block">${kit.esc(SYS_EXTRA)}</span>The cropped photo again. What comes back for total?`,
        opts: ["null", `${TRUTH.total} again`, "No JSON at all, an apology instead"], right: ca.total === null ? 0 : ca.total === TRUTH.total ? 1 : 2,
        fb: [`Right. Total came back null${ca.currency === null ? ", and so did currency" : ""}: ${kit.esc(fieldList(nulls("cropped-allow")))}. The lines it could see kept their values. Now the app can catch it: a null total means “ask for a photo of the whole receipt”.`,
          `Not this time. Given a way to say “not visible”, the model used it: ${kit.esc(fieldList(nulls("cropped-allow")))} came back null.`,
          `It still answered with JSON. The only change: ${kit.esc(fieldList(nulls("cropped-allow")))} came back null.`] },
      { q: `Same new prompt, the blurred photo. What comes back?`,
        opts: ["null for the fields it cannot read", "Confident numbers again, still wrong", "Every field right, now that it may say null"], right: nulls("blurred-allow").length ? 0 : wrongOf("blurred-allow").length ? 1 : 2,
        fb: [`It used no nulls at all. ${plural(wrongNotNull("blurred-allow").length, "field")} came back filled and wrong: ${kit.esc(fieldList(wrongNotNull("blurred-allow")))}.`,
          `Right. ${(w => w[0].toUpperCase() + w.slice(1))(word(nulls("blurred-allow").length))} nulls, ${plural(wrongNotNull("blurred-allow").length, "wrong field")} (${kit.esc(fieldList(wrongNotNull("blurred-allow")))}): date ${kit.esc(ba.date)}, total ${kit.esc(ba.total)}. A missing line is easy to notice. A blurred digit still looks like some digit, so the model reads one. The rule “use null if you cannot read it for certain” depends on the model knowing what it cannot read.`,
          `The blur did not go away. ${plural(wrongNotNull("blurred-allow").length, "field")} came back wrong: ${kit.esc(fieldList(wrongNotNull("blurred-allow")))}.`] },
      { q: `Back to the first prompt. Before sending, the app runs a sharpening filter over the blurred photo (the unsharp mask from Pillow, a Python image library). What comes back?`,
        opts: ["Every field right", "Some fields still wrong"], right: wrongOf("sharpened").length ? 1 : 0,
        fb: [`The filter made the edges harder, not the digits clearer. ${plural(wrongOf("sharpened").length, "field")} still wrong: ${kit.esc(fieldList(wrongOf("sharpened")))}.`,
          `Right. ${plural(wrongOf("sharpened").length, "field")} still wrong: ${kit.esc(fieldList(wrongOf("sharpened")))} (total ${kit.esc(ANS.sharpened.total)}). A filter can only rearrange the pixels it has. The detail that told one digit from another was lost when the photo was taken, so the fix is a new photo.`] }
    ];
    const paint = () => {
      const upto = ans.findIndex((a, i) => a !== Q[i].right);
      const show = upto === -1 ? Q.length : upto + 1;
      el.innerHTML = `<h1>Predict three fixes</h1>
        <p class="lead">Same model, same request shape, temperature 0. Each change below was really run and recorded.</p>
        <div class="${P}pics">${fig(kit, "blurred", "Blurred, as sent")}${fig(kit, "sharpened", "Blurred, then sharpened in code")}</div>
        <p class="${P}cap">${CAPTION}</p>
        <p class="task">Predict each result. The next question opens when you have the last one right.</p>
        ${Q.slice(0, show).map((q, i) => `<div class="lcase" id="p${i}"><p>${q.q}</p>${kit.options(q.opts.map(kit.esc), { picked: ans[i], correct: q.right })}${ans[i] == null ? "" : kit.feedback(q.fb[ans[i]], ans[i] === q.right)}</div>`).join("")}
        ${upto === -1 ? kit.feedback(`So: allowing null fixes what is <b>out of frame</b>. Nothing in the prompt and no filter fixes pixels the camera <b>never caught</b>. That has to be caught before the call, while the person still has the receipt in hand.`) : ""}`;
      el.querySelectorAll(".lcase").forEach((c, i) => c.querySelectorAll("button").forEach(b => b.onclick = () => {
        ans[i] = +b.dataset.i; paint();
        if (ans.every((a, k) => a === Q[k].right)) done();
      }));
    };
    paint();
  }

  /* 5. Check the photo in code before the call: a blur score and a size check. */
  // The real function from docs/ai-path/runs/s5c-images-in/prep.py, line for line.
  const CODE = [
    "def grey(path):",
    "    return np.asarray(Image.open(path).convert(\"L\"), dtype=np.float64)",
    "",
    "def blur_score(path):",
    "    g = grey(path)",
    "    lap = (-4 * g[1:-1, 1:-1] + g[:-2, 1:-1] + g[2:, 1:-1] + g[1:-1, :-2] + g[1:-1, 2:])",
    "    return round(float(lap.var()), 1)"
  ];
  const SCORE_ROWS = [["clean", "Clean"], ["tilted", "Tilted"], ["cropped", "Cropped"], ["small", "Thumbnail"], ["blurred", "Blurred"], ["sharpened", "Sharpened"]];
  const BAD = ["blurred", "sharpened"];
  const LIMITS = [10, 100, 1500];
  const limitOk = t => SCORE_ROWS.every(([k]) => (BLUR[k] < t) === BAD.includes(k));
  // photos the model read right that a limit t would still refuse
  const tooHigh = t => SCORE_ROWS.filter(([k]) => BLUR[k] < t && !BAD.includes(k) && !wrongOf(k).length);
  // photos the model read right that score below the thumbnail, so any limit that refuses the thumbnail refuses them too
  const SMALL_ALSO = SCORE_ROWS.filter(([k]) => BLUR[k] < BLUR.small && !BAD.includes(k) && !wrongOf(k).length);
  function photoChecks({ el, done, kit }) {
    ensureStyle();
    let a1 = null, a2 = null;
    const right1 = LIMITS.findIndex(limitOk);
    const opts2 = [
      `Refuse photos narrower than a minimum width, and ask for a closer photo`,
      `Raise the blur limit so the thumbnail fails it too`,
      `Refuse tilted photos as well`
    ];
    const fb2 = [
      [`Right. The thumbnail is ${SENT_SIZE.small[0]} × ${SENT_SIZE.small[1]} pixels. Its digits are a few pixels tall, sharp but too small to tell apart. A size check is one comparison in code. Pick the minimum by testing real receipts: keep the smallest size at which your model still reads every field right.`, true],
      [`To refuse the thumbnail (${BLUR.small}), the limit must be above ${BLUR.small}. That also refuses ${SMALL_ALSO.map(([k, l]) => `the ${l.toLowerCase()} photo (${BLUR[k]})`).join(" and ")}, which the model read right, and leaves only ${(Math.round((BLUR.clean - BLUR.small) * 10) / 10)} points below the clean photo (${BLUR.clean}). Shrinking keeps edges hard; it just leaves too few pixels per digit.`, false],
      [`The tilt did no harm here. Of four turned copies (the ${PREP.tilt}° tilt, sideways, upside down, and the tilt at half size), the model read ${word(TILT_OK)} with every field right. Model makers' guides still warn that rotated text can be misread, and straightening is cheap: our script found the angle (${PREP.tilt}°) and turned the photo back${wrongOf("upright").length ? "" : ", and that read was right too"}. But the thumbnail is straight and still wrong.`, false]
    ];
    const paint = () => {
      const t = a1 == null ? null : LIMITS[a1];
      el.innerHTML = `<h1>Check the photo before the call</h1>
        <p class="lead">Blur can be measured in code. This function looks at how sharply each pixel differs from its four neighbours. Sharp text gives big differences, so a high score. A blurred photo gives a low one.</p>
        <div class="${P}wrap">${kit.code(CODE, -1)}</div>
        <p class="lead"><code>g</code> is the photo as a grid of grey levels (a NumPy array). Each <code>g[…]</code> slice is that whole grid shifted one pixel up, down, left or right, so <code>lap</code> is “the four neighbours minus 4 × the pixel”, worked out for every pixel at once. <code>var()</code> (the variance) says how spread out those differences are: a wide spread means hard edges.</p>
        <table class="${P}scores"><thead><tr><th>photo</th><th>blur score</th><th>model's answer</th></tr></thead><tbody>
          ${SCORE_ROWS.map(([k, label]) => `<tr><td>${label}</td><td class="n">${BLUR[k]}</td><td>${wrongOf(k).length ? plural(wrongOf(k).length, "wrong field") : k === "cropped" ? "matches the paper, total guessed" : "matches the paper"}</td></tr>`).join("")}
        </tbody></table>
        <p class="${P}cap">A higher score means sharper edges. Scores from prep.py, run on this lesson's photos. The answers are the recordings you saw.</p>
        <p class="task">The app refuses a photo whose score is below a limit and asks for a retake. Pick the limit that refuses the blurred and the sharpened photo and keeps the others.</p>
        <div class="lpanel" id="q1">${kit.options(LIMITS.map(String), { picked: a1, correct: right1, num: true })}
        ${a1 == null ? "" : a1 === right1
          ? kit.feedback(`Right. Below ${t}: ${BAD.map(k => SCORE_ROWS.find(r => r[0] === k)[1].toLowerCase()).join(" and ")} (${BAD.map(k => BLUR[k]).join(" and ")}). Everything else is far above. This limit fits these photos; a real app sets it from a sample of its own receipts.`, true)
          : kit.feedback(tooHigh(t).length
            ? `${t} also refuses ${tooHigh(t).map(([, l]) => l.toLowerCase()).join(" and ")} (${tooHigh(t).map(([k]) => BLUR[k]).join(" and ")}), and the model read ${tooHigh(t).length > 1 ? "those" : "that one"} right. A limit that high sends good photos back.`
            : `${t} lets the sharpened photo through: it scores ${SHARP}. The filter raised the score a little and the answer stayed wrong.`, false)}</div>
        ${a1 === right1 ? `<div class="lcase" id="q2"><p>One wrong photo passes the blur check: the thumbnail, at ${BLUR.small}. Which check catches it?</p>${ask(kit, opts2.map(kit.esc), 0, a2, fb2)}</div>` : ""}`;
      el.querySelectorAll("#q1 button").forEach(b => b.onclick = () => { a1 = +b.dataset.i; if (a1 !== right1) a2 = null; paint(); });
      el.querySelectorAll("#q2 button").forEach(b => b.onclick = () => { a2 = +b.dataset.i; paint(); if (a1 === right1 && a2 === 0) done(); });
    };
    paint();
  }

  /* 6. What an image costs: predict the token count of the thumbnail. */
  function tokenCost({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const big = R.clean.promptTokens, sm = R.small.promptTokens, md = R.medium.promptTokens;
    const ratio = pxRatio("clean", "small");
    const opts = [`About ${ratio} times fewer`, "About half", "The same"];
    const right = sm === big ? 2 : sm * 3 < big ? 0 : 1;
    const say = `The full photo used <b>${big}</b> prompt tokens, the thumbnail <b>${sm}</b>, and a half-width copy <b>${md}</b>. All three calls carried the same text, so the image counted the same at every size.`;
    const fb = [
      [`${say} Some models do count tokens by image size, so on those a smaller photo is cheaper. This one did not.`, false],
      [`${say} The image cost did not change with its size on this model.`, false],
      [`Right. ${say} On this model, in this run, shrinking saved nothing and cost ${plural(wrongOf("small").length, "wrong field")}.`, true]
    ];
    const paint = () => {
      el.innerHTML = `<h1>What does one photo cost?</h1>
        <p class="lead">Every image you send becomes input tokens, the same budget as text. The thumbnail has ${SENT_SIZE.small[0]} × ${SENT_SIZE.small[1]} pixels, the full photo ${SENT_SIZE.clean[0]} × ${SENT_SIZE.clean[1]}: about ${ratio} times more pixels. The API reports the prompt tokens of every call.</p>
        <p class="task">Predict: how many prompt tokens did the thumbnail call use, compared with the full photo?</p>
        <div class="lpanel">${ask(kit, opts.map(kit.esc), right, ans, fb)}
        ${ans === right ? kit.feedback(`How images turn into tokens is different for each provider and model. Anthropic's guide says larger images cost more tokens, up to a size where it shrinks them first. OpenAI's counts the image in small squares or tiles, depending on the model. Google's guide describes counting large images in tiles, yet this run with a Google model reported the same count at three sizes. So do not guess. Read the token usage your API reports for your real photos before you decide to shrink. Never shrink below the size where the digits stay readable. And in a chat, a base64 image (the photo written out as text) is sent again with every turn.`) : ""}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === right) done(); });
    };
    paint();
  }

  /* 7. The big picture, with a task. */
  function bigPicture({ el, done, kit }) {
    ensureStyle();
    let ans = null;
    const opts = [
      "Every company card payment already arrives from the bank feed with amount, date and merchant. Finance wants totals per month.",
      "A toll company reads the ticket number on one printed ticket layout, fifty thousand times a day, and needs every character exact.",
      "Engineers photograph handwritten delivery notes from hundreds of small suppliers, each with its own layout. A few dozen a day, and a clerk confirms each one."
    ];
    const fb = [
      ["The facts already exist as data. A photo would turn exact numbers into pixels and back, and add a chance of misreading. Use the feed; ask for a receipt photo only where the feed is missing something.", false],
      ["One fixed layout at that volume is what OCR (software that turns pictures of printed text into text) plus a few rules is for: the field is always in the same place, it costs far less per page, and it gives the same output for the same input. The next lessons in this unit come back to OCR.", false],
      ["Right. Many layouts, handwriting and low volume are where a vision model earns its cost: no template to write per supplier. The clerk's check covers what this lesson showed: a confident answer can still be wrong.", true]
    ];
    const paint = () => {
      el.innerHTML = `<h1>When to send a photo to a model</h1>
        <p class="lead"><b>What it is for:</b> reading pictures whose layout you cannot predict: receipts from any shop, handwriting, forms you have never seen, pictures with no text at all.</p>
        <p class="lead"><b>Prepare it:</b> check sharpness and size in code and ask for a retake on the spot. Let the schema say null for what is not visible. Have a person review what matters.</p>
        <p class="lead"><b>When not:</b> the facts already exist as data (use the data); one fixed printed layout at high volume (OCR plus rules); a barcode or QR code (a decoder).</p>
        <p class="lead"><b>What it costs:</b> image tokens on every call, slower calls, the photo leaves your system (card digits, names), and wrong answers that look right.</p>
        <p class="task">Which job calls for sending images to a vision model?</p>
        <div class="lpanel">${ask(kit, opts.map(kit.esc), 2, ans, fb)}</div>`;
      el.querySelectorAll(".lopts button").forEach(b => b.onclick = () => { ans = +b.dataset.i; paint(); if (ans === 2) done(); });
    };
    paint();
  }

  /* 8. Recognise it in new situations, including two "no" cases. */
  const CASES = [
    ["A hotel asks guests to fill in handwritten feedback cards, in several languages. Staff photograph the cards, and the manager wants the complaints grouped each week.", true,
      "Yes. Handwriting in several languages, a few cards a day, and a summary a person reads. Check each photo for blur when it is taken, so a retake happens at the desk, not a week later.",
      "Handwriting and mixed languages are hard for plain OCR, and the volume is small. A vision model fits; check each photo for blur when it is taken, and let the manager read the result."],
    ["Every parcel in a warehouse carries a printed QR code with its parcel id. The team wants a model to read the id from a photo of each label.", false,
      "Right, no. A QR code is made to be decoded by software: a decoder returns the exact id, the same every time, for free. A model could misread one character, and each call costs tokens and time.",
      "A QR code is built for a decoder, which returns the exact id the same way every time, at no cost per scan. A model guesses characters from pixels and can misread one, which sends the parcel to the wrong place."],
    ["A shop chain wants to know which shelves have empty gaps. Staff photograph each shelf once a day, and someone follows up on the gaps.", true,
      "Yes. There is no text to extract, the shelves all look different, and a person follows up. OCR has nothing to read here; a vision model can describe what it sees.",
      "OCR reads text, and there is no text here. The shelves differ from shop to shop. Describing what a picture shows is what a vision model does, and a person still checks the gaps."],
    ["Users type their bank account number into a form. To be safe, the team wants to screenshot the filled form and ask a model to confirm the number looks valid.", false,
      "Right, no. The number is already text. Turning it into pixels and asking a model adds a chance of a misread. A bank account number such as an IBAN has a check-digit rule, which code can test exactly.",
      "The number already exists as text, so a picture of it only adds a chance of misreading. An IBAN has check digits that code tests exactly, the same way every time."]
  ];
  function recognise({ el, done, kit }) {
    ensureStyle();
    const ans = CASES.map(() => null);
    const paint = () => {
      el.innerHTML = `<h1>Would you send a picture here?</h1>
        <p class="lead">${word(CASES.length)[0].toUpperCase() + word(CASES.length).slice(1)} situations, away from receipts.</p>
        <p class="task">For each one, decide whether sending images to a vision model is the right tool. Pick again if you change your mind.</p>
        ${CASES.map(([q, y, yes, no], i) => `<div class="lcase" id="c${i}"><p>${kit.esc(q)}</p>${kit.options(["Yes", "No"], { picked: ans[i], correct: y ? 0 : 1 })}${ans[i] == null ? "" : kit.feedback(kit.esc(ans[i] === (y ? 0 : 1) ? yes : no), ans[i] === (y ? 0 : 1))}</div>`).join("")}`;
      el.querySelectorAll(".lcase").forEach((c, i) => c.querySelectorAll("button").forEach(b => b.onclick = () => {
        ans[i] = +b.dataset.i; paint();
        if (CASES.every(([, y], j) => ans[j] === (y ? 0 : 1))) done();
      }));
    };
    paint();
  }

  /* 9. What next. */
  function whatNext({ el, done, kit, topic }) {
    ensureStyle();
    const nx = topic && topic.next;
    el.innerHTML = `<h1>You can prepare a photo for a model</h1>
      <p class="lead">You compared real answers for one receipt photographed four ways. Blur and a tiny thumbnail gave confident wrong numbers that still added up. A cropped photo got a total that was never in it. Allowing null caught the crop and not the blur. A filter did not bring the digits back. A blur score and a size check in code catch the blurred and the tiny photos before the call. You also know when a photo is the wrong input: the data exists, the layout is fixed, or a code is made for a decoder.</p>
      <p class="lead">This lesson was the practice: there is no separate exercise.</p>
      ${nx ? `<p class="lead"><b>Next:</b> ${kit.esc(nx.title)}. ${nx.id === "s5c-speech" ? "Wind in a voice note plays the part blur played here. There you measure the errors with one number, the word error rate." : kit.esc(nx.outcome || "")}</p>` : ""}`;
    done();
  }

  LessonKit.define(ID, {
    title: "Sending images to a model",
    checked: "2026-11-14",
    sources: [
      "https://aistudio.google.com/docs/image-understanding",
      "https://developers.openai.com/api/docs/guides/images-vision",
      "https://platform.claude.com/docs/en/build-with-claude/vision",
      "https://openrouter.ai/docs/guides/overview/multimodal/image-understanding",
      "https://pillow.readthedocs.io/en/stable/reference/ImageFilter.html",
      "https://www.ecb.europa.eu/paym/target/consolidation/profuse/shared/pdf/ecb.t2cr250205_t2_0142_sys_iban_checksum_validation_A2A.en.pdf"
    ],
    interview: [{
      q: "Your expense app reads receipt photos with a vision model. Finance says a few totals each month are wrong, and they only notice at month end. What do you change?",
      good: [
        "Check the photo in code at capture time (a blur score and a minimum size) and ask for a retake while the person still has the receipt",
        "Let the schema return null for a field that is not visible, and send nulls to a person instead of guessing",
        "Do not trust a check that only compares the answer with itself: a blurred receipt can come back wrong and still add up",
        "Build a small labelled set of real receipt photos and measure accuracy per field before and after each change",
        "Cross-check against data you already have, such as the card payment amount, and use that data instead of a photo where it exists"
      ],
      weak: "Switch to a bigger model or tell it to be careful in the prompt. Neither brings back pixels a blurred photo never had, and the model still will not say which fields it guessed."
    }],
    screens: [markWrong, sumCheck, spotIdea, predictFixes, photoChecks, tokenCost, bigPicture, recognise, whatNext],
    walk: [
      { wrong: ['[data-k="tilted:tip"]'], right: TARGETS.map(k => `[data-k="${k}"]`) },
      { wrong: ["#c0 [data-wrong]"], right: ["#c0 [data-right]", "#c1 [data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["#p0 [data-wrong]"], right: ["#p0 [data-right]", "#p1 [data-right]", "#p2 [data-right]"] },
      { wrong: ["#q1 [data-wrong]"], right: ["#q1 [data-right]", "#q2 [data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["[data-wrong]"], right: ["[data-right]"] },
      { wrong: ["#c1 [data-wrong]"], right: CASES.map((_, i) => `#c${i} [data-right]`) },
      { right: [] }
    ]
  });
})();
